                $StartServiceResult = [AtomicTestHarnesses_T1543_003.ProcessNativeMethods]::StartService(
                    $ServiceHandle, # hService
                    0,              # dwNumServiceArgs
                    [IntPtr]::Zero  # lpServiceArgVectors
