    }
    switch ($ServiceType){

        'Win32OwnProcess'{
            Start-Sleep 1
            $ServiceInfo = Get-ItemProperty -Path HKLM:\SYSTEM\CurrentControlSet\Services\$ServiceName\ -ErrorAction Ignore
            if ($null -ne $ServiceInfo){
